//---------------------------------------------------------------------------//
// Import
//---------------------------------------------------------------------------//

import React from 'react';

//---------------------------------------------------------------------------//
// Component
//---------------------------------------------------------------------------//

const Component = (props) => {
    return (
        <>
            <iframe
                title='Api Documentation'
                src="swagger.html"
                style={{
                    width:'calc(100% - 10px)',
                    height:'calc(100vh - 74px)'
                }}
            >
            </iframe>
        </>
    );
};

//---------------------------------------------------------------------------//
// Export
//---------------------------------------------------------------------------//

export default Component;


//---------------------------------------------------------------------------//