

const showBanner = (dispatch, type, message) => {
    dispatch({
        type: 'BANNER_MESSAGE',
        payload: {
            type: type,
            message: message
        }
    });
}

const bannerHide = (dispatch) => {
    dispatch({
        type: 'BANNER_HIDE'
    });
}

export default {showBanner, bannerHide}