
const initialState = {
    scopes: [],
    policies: [],
    protocols: [],
    scopeCount: 0
};

const reducer = (state = initialState, action) => {

    const newState = {...state}

    switch (action.type) {

        case 'QOS_SET_STATE': {
            return {
                ...state, 
                ...action.payload
            }
        }

        default: {
            break;
        }
    }
    return newState;
};

export default reducer;
